// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Cooler} from "../src/Cooler.sol";

contract InvMutTest is Test {
    Cooler c;
    function setUp() public { c = new Cooler(); }

    function testFuzz_property(address actor, address to_, uint256 loanID) public {
        vm.assume(actor != address(0)); // the lender of a non-existent loan is address(0), so any real actor is NOT the lender
        vm.assume(to_ != address(0));

        bool ok;
        vm.prank(actor);
        try c.approveTransfer(to_, loanID) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: a non-lender can never cause an approval to be stored for any loan id.
        assertTrue(
            !ok || c.approvals(loanID) == address(0),
            "non-lender must not set approvals"
        );
    }
}
